package main

import (
  "fmt"
  "os"
  "time"
)

func main() {
  fmt.Printf("Go container %s @ %s\n", os.Getenv("HOSTNAME"), time.Now().Format(time.RFC3339))
}

from flask import Flask, jsonify
from datetime import datetime

app = Flask(__name__)

@app.route('/')
def root():
  return jsonify({"lang": "python", "time": datetime.utcnow().isoformat()})

if __name__ == '__main__':
  app.run(host='0.0.0.0', port=7003)
